def _activity_pair_height(n_agents, base=ACTIVITY_PAIR_CHART_HEIGHT, row_px=36, pad=160):
    """ارتفاع موحّد لزوج الشارتات جنب بعض حسب عدد المحصلين."""
    n = max(int(n_agents or 0), 1)
    return max(base, row_px * n + pad)

